/bin/bash -lc "python - <<'PY'
import numpy as np
# use purple list from file quickly redetect
from scipy import ndimage
A=np.load('source_pixels.npz')['rgb']; tracks=[]
for typ in ['p','o']:
 xs=[]
 prev=228 if typ=='p' else 27
 for t in range(96):
  r,g,b=A[t].astype(float).transpose(2,0,1); yy=np.indices(r.shape)[0]
  if typ=='p':m=(r>70)&(b>70)&(b>g*1.12)&(r>g*1.05)&(np.maximum(r,b)-g>18)&(yy<100)
  else:m=(r>125)&(r>g+18)&(g>b+18)&(yy>45)&(yy<90)
  l,n=ndimage.label(m); C=[]
  for k in range(1,n+1):
   y,x=np.where(l==k)
   if len(x)>=30:C.append((len(x),x.mean()))
  s=min(C,key=lambda c:abs(c[1]-prev));prev=s[1];xs.append(prev)
 tracks.append(np.array(xs))
for name,x in zip(['p','o'],tracks):
 for seg in [(8,30),(38,53),(58,68)]:
  lo,hi=seg; v=(x[lo+1:hi+1]-x[lo-1:hi-1])/2;a=x[lo+1:hi+1]-2*x[lo:hi]+x[lo-1:hi-1];xx=x[lo:hi]
  # a = b0 + b1 sign + b2 v
  X=np.c_[np.ones(len(v)),np.sign(127.5-xx),v]
  co=np.linalg.lstsq(X,a,rcond=None)[0]
  print(name,seg,'const sign drag',co,'mean a',a.mean(),'v',v.min(),v.max())
PY"
